<?php
require_once dirname(__DIR__).'/includes/functions.php';require_content_manager();$jobs=$con->query('SELECT j.*,c.title career_title,(SELECT COUNT(*) FROM job_applications a WHERE a.job_id=j.id) application_count FROM job_opportunities j LEFT JOIN careers c ON c.id=j.career_id ORDER BY j.created_at DESC');$careers=$con->query('SELECT id,title FROM careers WHERE is_active=1 ORDER BY title');$pageTitle='Job opportunities';require __DIR__.'/includes/header.php';?>
<section class="d-flex flex-column flex-sm-row justify-content-between align-items-sm-end gap-3 mb-4"><div><div class="admin-page-kicker">Employment content</div><h1 class="h3">Job opportunities</h1><p class="text-muted mb-0">Publish opportunities that students can apply to with their career profile.</p></div><button class="btn btn-primary create-action" id="addJob"><i class="bi bi-plus-circle me-2"></i>Add job</button></section>
<div class="card overflow-hidden"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Opportunity</th><th>Type</th><th>Closes</th><th>Applications</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($jobs as $j):?><tr><td><strong><?=e($j['title'])?></strong><div class="small text-muted"><?=e($j['company'])?> · <?=e($j['location'])?></div></td><td><?=e(ucwords(str_replace('_',' ',$j['employment_type'])))?></td><td><?=e($j['closing_date']?:'Open')?></td><td><?=$j['application_count']?></td><td><span class="status-pill <?=$j['is_active']?'status-active':'status-inactive'?>"><?=$j['is_active']?'Active':'Inactive'?></span></td><td class="text-end"><button class="btn btn-sm btn-outline-primary edit-job" data-row='<?=e(json_encode($j))?>'>Edit</button></td></tr><?php endforeach?></tbody></table></div></div>
<div class="modal fade" id="jobModal"><div class="modal-dialog modal-lg"><form class="modal-content" action="<?=url('admin/save_job.php')?>" method="post" data-ajax><div class="modal-header"><h2 class="modal-title fs-5">Job opportunity</h2><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id"><div class="row g-3"><div class="col-md-7"><label class="form-label">Job title</label><input class="form-control" name="title" maxlength="150" required></div><div class="col-md-5"><label class="form-label">Company</label><input class="form-control" name="company" maxlength="150" required></div><div class="col-md-6"><label class="form-label">Location</label><input class="form-control" name="location" maxlength="150"></div><div class="col-md-6"><label class="form-label">Opportunity type</label><select class="form-select" name="employment_type" required><?php foreach(['internship','learnership','part_time','full_time','contract'] as $x):?><option value="<?=$x?>"><?=e(ucwords(str_replace('_',' ',$x)))?></option><?php endforeach?></select></div><div class="col-md-7"><label class="form-label">Related career</label><select class="form-select" name="career_id"><option value="">Not career-specific</option><?php foreach($careers as $c):?><option value="<?=$c['id']?>"><?=e($c['title'])?></option><?php endforeach?></select></div><div class="col-md-5"><label class="form-label">Closing date</label><input class="form-control" type="date" name="closing_date"></div><div class="col-12"><label class="form-label">Description</label><textarea class="form-control" name="description" rows="5" required></textarea></div><div class="col-12"><label class="form-label">Requirements</label><textarea class="form-control" name="requirements" rows="4"></textarea></div><div class="col-12"><label class="form-check"><input class="form-check-input" type="checkbox" name="is_active" checked> Visible and accepting applications</label></div></div></div><div class="modal-footer"><button type="button" class="btn btn-light" data-bs-dismiss="modal">Cancel</button><button class="btn btn-primary">Save opportunity</button></div></form></div></div>
<script>const jm=document.getElementById('jobModal'),jf=jm.querySelector('form');document.getElementById('addJob').onclick=()=>{jf.reset();jf.elements.id.value='';jf.elements.is_active.checked=true;bootstrap.Modal.getOrCreateInstance(jm).show()};document.querySelectorAll('.edit-job').forEach(b=>b.onclick=()=>{const r=JSON.parse(b.dataset.row);Object.keys(r).forEach(k=>{if(jf.elements[k])jf.elements[k].type==='checkbox'?jf.elements[k].checked=+r[k]===1:jf.elements[k].value=r[k]??''});bootstrap.Modal.getOrCreateInstance(jm).show()});</script>
